import{_ as t,o,c as a,a2 as l}from"./chunks/framework.Crpw6aS5.js";const i=JSON.parse('{"title":"2001年 · 诺亚法则","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/2001年.md","filePath":"05_quotes/by-year/2001年.md"}'),r={name:"05_quotes/by-year/2001年.md"};function u(s,e,c,h,q,_){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_2001年-·-诺亚法则" tabindex="-1">2001年 · 诺亚法则 <a class="header-anchor" href="#_2001年-·-诺亚法则" aria-label="Permalink to &quot;2001年 · 诺亚法则&quot;">​</a></h1><blockquote><p>预测下雨不算数；建造方舟才算数。——巴菲特（71岁）</p></blockquote><p>本页收录2001年致股东信中的经典语录。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>我违反了诺亚法则：预测下雨不算数，建造方舟才算数。因此，我让伯克希尔以危险的风险水平运营——尤其是在通用再保险。我很遗憾地说，我们尚未获得补偿的大量风险仍留在我们的账本上，但它每天都在逐渐消散。</p></blockquote><blockquote><p>只有当潮水退去时，你才知道谁在裸泳。</p></blockquote><blockquote><p>许多现在跌倒的终将复兴，许多现在荣耀的终将跌落。</p></blockquote><blockquote><p>损失没有&quot;发展&quot;——它们一直都在那里。发展的是管理层对损失的理解。</p></blockquote><blockquote><p>我可以为你做任何事——任何事——你想要的。只要告诉我你想要什么。他毫不犹豫地回答：&quot;重新定价我的期权。&quot;</p></blockquote><blockquote><p>我们应该选择那些拥有巨大且真实所有权利益的董事——他们或其家族购买的股票，而不是伯克希尔赠送或通过期权获得的股票。</p></blockquote><blockquote><p>当潮水退去时，才知道谁在裸泳。</p></blockquote><blockquote><p>如果首席执行官一边敦促投资者买入股票，一边自己却在抛售，有时还使用隐藏其行为的手法，视股东为待宰的肥羊，而非合作伙伴。</p></blockquote><blockquote><p>我们从未有过任何一家子公司的CEO选择离开伯克希尔去别处工作。</p></blockquote><blockquote><p>保险公司创造卓越的长期业绩主要是通过避免愚蠢决策，而非做出英明决策。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>2001年是充满冲击的一年：9·11恐怖袭击导致保险业蒙受史上最大单次损失，伯克希尔浮存金成本飙升至12.8%，公司净值亏损37.7亿美元。巴菲特在信中公开承认自己犯下了重大错误——在承保9·11相关风险时忽视了&quot;诺亚法则&quot;，明知恐怖主义威胁却未采取行动保护公司。这一年也是他罕见的公开自我批评之年。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-2001年-翻译-·-01-letters-2001年-核心总结-·-01-letters-2001年-思维导图" tabindex="-1"><a href="/01_letters/2001年/翻译.html">01_letters/2001年/翻译</a> · <a href="/01_letters/2001年/核心总结.html">01_letters/2001年/核心总结</a> · <a href="/01_letters/2001年/思维导图.html">01_letters/2001年/思维导图</a> <a class="header-anchor" href="#_01-letters-2001年-翻译-·-01-letters-2001年-核心总结-·-01-letters-2001年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/2001年/翻译]] · [[→ 核心总结|01_letters/2001年/核心总结]] · [[→ 思维导图|01_letters/2001年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/2001年/翻译.html">/01_letters/2001年/翻译</a></li></ul>',23)])])}const p=t(r,[["render",u]]);export{i as __pageData,p as default};
